import{_ as e,o,c as n,a7 as a}from"./chunks/framework.C4ZIv4ii.js";const i="/falconcms/screenshots/builder-canvas.webp",m=JSON.parse('{"title":"Containers & Columns","description":"","frontmatter":{},"headers":[],"relativePath":"builder/containers.md","filePath":"builder/containers.md","lastUpdated":1788707293000}'),s={name:"builder/containers.md"};function r(l,t,d,h,c,u){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="containers-columns" tabindex="-1">Containers &amp; Columns <a class="header-anchor" href="#containers-columns" aria-label="Permalink to &quot;Containers &amp; Columns&quot;">​</a></h1><p>Every Falcon Builder layout starts with Containers, which hold Columns, which hold Elements.</p><p><img src="'+i+'" alt="Containers and columns in the builder"></p><p><em>The navigator on the left shows the nesting: a container holds columns, a column can hold a nested row, and elements sit at the leaves.</em></p><h2 id="containers" tabindex="-1">Containers <a class="header-anchor" href="#containers" aria-label="Permalink to &quot;Containers&quot;">​</a></h2><p>A container is a full-width row on your page. Click <strong>+ Add Container</strong> to open the Column Select modal.</p><h3 id="container-settings" tabindex="-1">Container Settings <a class="header-anchor" href="#container-settings" aria-label="Permalink to &quot;Container Settings&quot;">​</a></h3><p>Right-click the container toolbar or click the gear icon:</p><p><strong>Layout:</strong></p><ul><li>Background color, gradient, or image</li><li>Background position and size</li><li>Min height</li><li>Padding (top, right, bottom, left)</li><li>Margin</li></ul><p><strong>Advanced:</strong></p><ul><li>CSS Class, CSS ID</li><li>Custom CSS</li><li>Animation on scroll (fade in, slide up, zoom)</li><li>Sticky (sticks to top on scroll)</li></ul><p><strong>Visibility:</strong></p><ul><li>Show/hide on Desktop, Tablet, Mobile</li></ul><h3 id="container-toolbar-actions" tabindex="-1">Container Toolbar Actions <a class="header-anchor" href="#container-toolbar-actions" aria-label="Permalink to &quot;Container Toolbar Actions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Icon</th><th>Action</th></tr></thead><tbody><tr><td>↕</td><td>Drag to reorder the container</td></tr><tr><td>✏️</td><td>Edit container settings</td></tr><tr><td>📋</td><td>Duplicate container</td></tr><tr><td>📚</td><td>Save to Library</td></tr><tr><td>🌐</td><td>Save as Global Section</td></tr><tr><td>🗑️</td><td>Delete container</td></tr></tbody></table><hr><h2 id="column-layouts" tabindex="-1">Column Layouts <a class="header-anchor" href="#column-layouts" aria-label="Permalink to &quot;Column Layouts&quot;">​</a></h2><p>When adding a container, choose from preset column layouts:</p><table tabindex="0"><thead><tr><th>Layout</th><th>Description</th></tr></thead><tbody><tr><td><code>1/1</code></td><td>Single full-width column</td></tr><tr><td><code>1/2 + 1/2</code></td><td>Two equal columns</td></tr><tr><td><code>1/3 + 2/3</code></td><td>Narrow + wide</td></tr><tr><td><code>2/3 + 1/3</code></td><td>Wide + narrow</td></tr><tr><td><code>1/3 + 1/3 + 1/3</code></td><td>Three equal columns</td></tr><tr><td><code>1/4 + 3/4</code></td><td>Sidebar + main</td></tr><tr><td><code>1/4 + 1/4 + 1/4 + 1/4</code></td><td>Four equal columns</td></tr></tbody></table><p>More layouts are available in the modal. Custom ratios can be set in column settings.</p><hr><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>Each column inside a container holds one or more elements.</p><h3 id="column-settings" tabindex="-1">Column Settings <a class="header-anchor" href="#column-settings" aria-label="Permalink to &quot;Column Settings&quot;">​</a></h3><p>Click the column toolbar:</p><p><strong>Size:</strong></p><ul><li>Width percentage (responsive: desktop, tablet, mobile)</li><li>Padding</li></ul><p><strong>Background:</strong></p><ul><li>Background color or image</li></ul><p><strong>Vertical Align:</strong></p><ul><li>Top, Middle, Bottom, Stretch</li></ul><p><strong>Advanced:</strong></p><ul><li>CSS Class, CSS ID</li><li>Custom CSS</li></ul><h3 id="responsive-column-widths" tabindex="-1">Responsive Column Widths <a class="header-anchor" href="#responsive-column-widths" aria-label="Permalink to &quot;Responsive Column Widths&quot;">​</a></h3><p>Each column can have different widths per device:</p><table tabindex="0"><thead><tr><th>Device</th><th>Example</th></tr></thead><tbody><tr><td>Desktop</td><td>1/3 (33%)</td></tr><tr><td>Tablet</td><td>1/2 (50%)</td></tr><tr><td>Mobile</td><td>1/1 (100%)</td></tr></tbody></table><p>This makes your layout naturally stack on mobile.</p><hr><h2 id="adding-elements-to-columns" tabindex="-1">Adding Elements to Columns <a class="header-anchor" href="#adding-elements-to-columns" aria-label="Permalink to &quot;Adding Elements to Columns&quot;">​</a></h2><p>Click the <strong>+</strong> button inside a column to open the Element Select modal. Choose an element type and it&#39;s inserted into the column.</p><p>Elements can be dragged within a column or between columns.</p><hr><h2 id="nested-columns" tabindex="-1">Nested Columns <a class="header-anchor" href="#nested-columns" aria-label="Permalink to &quot;Nested Columns&quot;">​</a></h2><p>A column can hold a <strong>nested row</strong> — a row of columns inside a column — for layouts a single grid cannot express: a sidebar card split in two, a feature block with its own inner columns. Add one from a column&#39;s toolbar (<strong>Add Nested</strong>).</p><h3 id="open-work-finish" tabindex="-1">Open, work, finish <a class="header-anchor" href="#open-work-finish" aria-label="Permalink to &quot;Open, work, finish&quot;">​</a></h3><p>A nested row is drawn <strong>closed</strong>: it shows its content, with a small orange panel sitting on it carrying a pencil and a <strong>+</strong>. Nothing inside can be clicked while it is closed, so a stray click meant for the page cannot land in it.</p><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td>✏️ <strong>pencil</strong></td><td>Opens the nested columns for editing</td></tr><tr><td>➕ <strong>plus</strong></td><td>Adds an element to the <strong>parent</strong> column, beside the nested row</td></tr><tr><td>hover the panel</td><td>Expands it to Duplicate, Delete and Drag</td></tr></tbody></table><p>While it is open you work inside it exactly as in any column — add elements, edit them, drag them. Everything outside dims and stops responding, and no new container or column can be started, so half-finished nested work cannot be left behind by a click elsewhere.</p><p>Finish with the <strong>✓ tick</strong> on the bar at the bottom of the row (<strong>✕</strong> does the same). That closes it, releases the rest of the canvas, and is the point at which <strong>Save</strong> becomes available for the work you just did inside.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Editing inside a nested row does not arm the Save button on its own — the Finished tick does. Everywhere else in the builder, Save still arms the moment you change anything. Press ✓ before you leave the page.</p></div><p>An empty nested row shows a placeholder bar instead of content, and the <strong>Preview</strong> toggle ignores all of this and draws the real page.</p><hr><h2 id="responsive-preview" tabindex="-1">Responsive Preview <a class="header-anchor" href="#responsive-preview" aria-label="Permalink to &quot;Responsive Preview&quot;">​</a></h2><p>Use the device buttons at the top of the builder to preview your layout on:</p><ul><li>🖥 Desktop</li><li>📱 Tablet</li><li>📲 Mobile</li></ul><p>The canvas resizes and shows how the layout looks on each device.</p><hr><h2 id="saving-publishing" tabindex="-1">Saving &amp; Publishing <a class="header-anchor" href="#saving-publishing" aria-label="Permalink to &quot;Saving &amp; Publishing&quot;">​</a></h2><ul><li><strong>Autosave</strong> runs every 30 seconds</li><li>Closing the tab with unsaved changes now asks you first — in the builder and on every admin screen. Note that work inside an open nested row is not counted as unsaved until you press its ✓ tick, so finish nested rows before you leave</li><li>Click <strong>Save Draft</strong> to save without publishing</li><li>Click <strong>Publish / Update</strong> to make changes live</li><li>View <strong>Revisions</strong> to restore any previous version</li></ul>',60)])])}const g=e(s,[["render",r]]);export{m as __pageData,g as default};
